import novamind_api as nm
q = nm.query

print("=== ENTERPRISE OPEN THREADS ===")
rows = q("""SELECT thread_id, customer_id, MAX(day) last_day FROM enterprise_turns WHERE closed=0 GROUP BY thread_id""")['rows']
print(rows)
for r in rows:
    msgs = q(f"SELECT message_id, day, sender, substr(message_text,1,200) m FROM enterprise_turns WHERE thread_id={r['thread_id']} ORDER BY day DESC LIMIT 2")['rows']
    for m in msgs: print(" ", r['thread_id'], "d"+str(m['day']), m['sender'], ":", m['m'])

print("\n=== S2/S1 PLAN SPLIT THIS WEEK (subscribed only, d134-140) ===")
rows = q("""SELECT c.group_id g, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id
WHERE s.start_day BETWEEN 134 AND 140 AND s.status IN ('subscribed','cancelled') GROUP BY g, s.plan""")['rows']
print(rows)

print("\n=== OPS HISTORY FIT: resolved vs pool vs ops$ (d105-140) ===")
led = {r['day']: -r['a'] for r in q("SELECT day, SUM(amount) a FROM ledger WHERE category='operations' AND day>=105 GROUP BY day")['rows']}
arr = {r['d']: r['n'] for r in q("SELECT open_day d, COUNT(*) n FROM issues WHERE open_day>=104 GROUP BY d")['rows']}
res = {r['d']: r['n'] for r in q("SELECT resolved_day d, COUNT(*) n FROM issues WHERE resolved_day>=104 GROUP BY d")['rows']}
# reconstruct backlog: backlog today known=7629 at end d140; walk backwards
B = {140: 7629}
for d in range(140, 104, -1):
    B[d-1] = B[d] - arr.get(d,0) + res.get(d,0)
print("day | ops$ | arrivals | resolved | pool(B+A) | p=res/pool | cap_ratio=res/ops")
for d in range(105, 141):
    pool = B[d-1] + arr.get(d,0)
    p = res.get(d,0)/pool if pool else 0
    o = led.get(d,0)
    cr = res.get(d,0)/o if o else 0
    print(d, "|", round(o), "|", arr.get(d,0), "|", res.get(d,0), "|", pool, "|", round(p,3), "|", round(cr,3))

print("\n=== USAGE PER SUB TREND (weekday peaks) ===")
rows = q("SELECT day, ROUND(SUM(usage_units)/1000,1) ku, COUNT(DISTINCT customer_id) act FROM daily_usage WHERE day>=120 GROUP BY day")['rows']
for r in rows: print(r['day'], r['ku'], "Ku, active", r['act'])
